// This file is generated by AI.

// 窗口形态: 开始界面用紧凑窗口, 打开项目后最大化。
//
// 为什么不是一直最大化: 开始界面只有"选一个项目"这一件事, 1280×800 的窗口里半屏是空的。
// 反过来, 编辑界面要同时放预览、侧栏与编辑器, 必须给足空间 —— 于是按"有没有打开项目"
// 切换形态, 用户不需要自己想起来去点最大化。

import { LogicalSize } from '@tauri-apps/api/dpi';
import { getCurrentWindow } from '@tauri-apps/api/window';

/**
 * 开始界面的窗口尺寸。
 *
 * 必须与 `tauri.conf.json` 里主窗口的 `width`/`height` 保持一致: 配置决定**首帧**大小,
 * 这里管之后每次回到开始界面的大小。不一致的话启动瞬间会看到一次跳动。
 */
export const WELCOME_WINDOW_SIZE = { width: 900, height: 620 };

/** 按当前页面切换窗口形态 (打开项目 -> 最大化; 回到开始界面 -> 紧凑 + 居中)。 */
export async function applyWindowMode(hasProject: boolean): Promise<void> {
  const win = getCurrentWindow();
  try {
    if (hasProject) {
      await win.maximize();
      return;
    }
    await win.unmaximize();
    await win.setSize(new LogicalSize(WELCOME_WINDOW_SIZE.width, WELCOME_WINDOW_SIZE.height));
    await win.center();
  } catch (error) {
    // 窗口没调成不该影响编辑: 大不了用户自己拖一下
    console.error('窗口形态切换失败', error);
  }
}
